@page "/settings"
@using sv_22b22392292c449eac36fa1b27f89635.Models

@rendermode InteractiveServer

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <div class="settings-sidebar-container">
        <SettingsSidebar ActiveSection="@_activeSection" OnSectionChanged="SetActiveSection" />
    </div>

    <div class="settings-content">
        @switch (_activeSection)
        {
            case "Profile":
                <ProfileSection />
                break;
            case "Notifications":
                <NotificationsSection />
                break;
            case "Security":
                <SecuritySection />
                break;
            case "Appearance":
                <AppearanceSection />
                break;
        }
    </div>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetActiveSection(string section)
    {
        _activeSection = section;
    }
}

.settings-dashboard {
    display: flex;
    gap: 2rem;
    min-height: 70vh;
}

.settings-sidebar-container {
    flex: 0 0 220px;
}

.settings-content {
    flex: 1;
    min-width: 0;
}

::deep .settings-sidebar {
    position: sticky;
    top: 1rem;
}

::deep .sidebar-title {
    padding: 0.75rem 1rem;
    margin-bottom: 0.5rem;
    color: #495057;
    font-weight: 600;
}

::deep .sidebar-link {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.6rem 1rem;
    border: none;
    border-radius: 0.5rem;
    background: transparent;
    color: #495057;
    text-align: left;
    width: 100%;
    cursor: pointer;
    transition: background-color 0.15s, color 0.15s;
    font-size: 0.95rem;
}

::deep .sidebar-link:hover {
    background-color: #e9ecef;
    color: #212529;
}

::deep .sidebar-link.active {
    background-color: #0d6efd;
    color: #fff;
}

::deep .sidebar-link.active:hover {
    background-color: #0b5ed7;
}

::deep .sidebar-icon {
    font-size: 1.1rem;
    width: 1.5rem;
    text-align: center;
}

::deep .settings-section {
    max-width: 800px;
}

::deep .avatar-preview img {
    object-fit: cover;
    border: 3px solid #dee2e6;
}

::deep .expand-icon {
    font-size: 0.8rem;
    color: #6c757d;
}

::deep .appearance-preview {
    transition: all 0.2s ease;
}

::deep .compact-preview p {
    margin-bottom: 0.25rem !important;
    line-height: 1.3;
}

